package com.nexodb.tools;
import java.nio.file.*;import java.util.Comparator;
public final class TeamWorkspaceServiceTest {public static void main(String[] args)throws Exception{Path root=Files.createTempDirectory("adisdb-team-");try{Files.writeString(root.resolve("V1__inicio.sql"),"CREATE TABLE t(id INT);");var service=new TeamWorkspaceService(root);var pending=service.migrationReviews().get(0);equal(TeamWorkspaceService.Decision.PENDING,pending.decision());service.review(pending.file(),pending.checksum(),TeamWorkspaceService.Decision.APPROVED,"Alex","Revisado");equal(TeamWorkspaceService.Decision.APPROVED,service.migrationReviews().get(0).decision());Files.writeString(root.resolve("V1__inicio.sql"),"CREATE TABLE t(id BIGINT);");equal(TeamWorkspaceService.Decision.PENDING,service.migrationReviews().get(0).decision());String report=service.report();if(report.contains("CREATE TABLE")||!report.contains("Migraciones aprobadas"))throw new AssertionError(report);System.out.println("TeamWorkspaceServiceTest: OK (review drift, analytics and private report)");}finally{try(var files=Files.walk(root)){for(Path file:files.sorted(Comparator.reverseOrder()).toList())Files.deleteIfExists(file);}}}private static void equal(Object e,Object a){if(!java.util.Objects.equals(e,a))throw new AssertionError("Expected "+e+" got "+a);}}
